output_text:
[
  {
    "id": "must_take_entry_cart",
    "text": "A shopper is obliged to collect the entrance cart before continuing the shopping trip.",
    "abstraction": {
      "state_properties": {
        "at_entry_cart_corral": "at(1,5)",
        "entry_cart_available": "cartAt(1,5)"
      },
      "events": {
        "take_entry_cart": {
          "pre": {
            "and": [
              "at_entry_cart_corral",
              "entry_cart_available",
              "PICKUP_CART"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "take_entry_cart"
    }
  },
  {
    "id": "items_require_cart",
    "text": "Picking up merchandise is prohibited unless the shopper currently has the cart.",
    "abstraction": {
      "state_properties": {
        "cart_possessed": "hasCart"
      },
      "events": {
        "pickup_merchandise": {
          "pre": "PICKUP_ITEM",
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "pickup_merchandise",
          {
            "not": "cart_possessed"
          }
        ]
      }
    }
  },
  {
    "id": "no_hand_carrying",
    "text": "Items should not be carried by hand; shoppers must avoid becoming handFull.",
    "abstraction": {
      "state_properties": {
        "carrying_by_hand": "handFull"
      },
      "events": {
        "hand_item_pickup": {
          "pre": {
            "and": [
              "PICKUP_ITEM",
              {
                "not": "hasCart"
              }
            ]
          },
          "post": "handFull"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "carrying_by_hand"
    }
  },
  {
    "id": "return_used_cart_front",
    "text": "After any item has been placed in the cart, the cart is obliged to be returned to the front bay at (0,1) before exit.",
    "abstraction": {
      "state_properties": {
        "front_cart_return_bay": "at(0,1)",
        "cart_parked_at_front_bay": "cartAt(0,1)"
      },
      "events": {
        "cart_used_for_item": {
          "pre": {
            "and": [
              "hasCart",
              "PICKUP_ITEM"
            ]
          },
          "post": "hasCart"
        },
        "return_cart_to_front_bay": {
          "pre": {
            "and": [
              "front_cart_return_bay",
              "hasCart",
              "LEAVE_CART"
            ]
          },
          "post": "cart_parked_at_front_bay"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "cart_used_for_item",
      "discharge": "return_cart_to_front_bay"
    }
  },
  {
    "id": "leave_cart_only_front_bay",
    "text": "Leaving a cart is permitted only at the front return bay, not in the shopping aisles or exit area.",
    "abstraction": {
      "state_properties": {
        "front_cart_return_bay": "at(0,1)"
      },
      "events": {
        "leave_cart_event": {
          "pre": "LEAVE_CART",
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "leave_cart_event",
          {
            "not": "front_cart_return_bay"
          }
        ]
      }
    }
  },
  {
    "id": "no_exit_with_cart",
    "text": "A shopper is prohibited from exiting while still possessing or pushing the cart.",
    "abstraction": {
      "state_properties": {
        "cart_possessed": "hasCart"
      },
      "events": {
        "exit_store": {
          "pre": "EXIT",
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "exit_store",
          "cart_possessed"
        ]
      }
    }
  },
  {
    "id": "exit_only_after_cart_parked",
    "text": "Exiting is prohibited unless the cart is already parked at the front return bay.",
    "abstraction": {
      "state_properties": {
        "cart_parked_at_front_bay": "cartAt(0,1)"
      },
      "events": {
        "exit_store": {
          "pre": "EXIT",
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "exit_store",
          {
            "not": "cart_parked_at_front_bay"
          }
        ]
      }
    }
  },
  {
    "id": "no_interactions_after_return",
    "text": "Once the cart has been returned to the front bay, the shopper should perform no further object interactions before exiting.",
    "abstraction": {
      "state_properties": {
        "cart_already_returned": "cartAt(0,1)"
      },
      "events": {
        "post_return_interaction": {
          "pre": {
            "and": [
              "cart_already_returned",
              "INTERACT"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "post_return_interaction"
    }
  }
]
